+            0x32 => InputKey::UppercaseM,
+            0x33 => InputKey::LessThan,
+            0x34 => InputKey::GreaterThan,
+            0x35 => InputKey::Question,
+            0x39 => InputKey::Space,
+            _ => InputKey::Ign,
+        }
+    }
+
+    fn ctrl_map(&self) -> InputKey {
+        match self.0 & 0x7F {
+            0x02 => InputKey::One,
+            0x03 => InputKey::Nul,
+            0x04 => InputKey::Esc,
+            0x05 => InputKey::Fs,
+            0x06 => InputKey::Gs,
+            0x07 => InputKey::Rs,
+            0x08 => InputKey::Us,
+            0x09 => InputKey::Del,
+            0x0A => InputKey::Nine,
+            0x0B => InputKey::Zero,
+            0x0C => InputKey::Us,
+            0x0D => InputKey::Equal,
+            0x0E => InputKey::Bs,
+            0x10 => InputKey::Dc1,
+            0x11 => InputKey::Etb,
+            0x12 => InputKey::Enq,
+            0x13 => InputKey::Dc2,
+            0x14 => InputKey::Dc4,
+            0x15 => InputKey::Em,
+            0x16 => InputKey::Nak,
+            0x17 => InputKey::Tab,
+            0x18 => InputKey::Si,
+            0x19 => InputKey::Dle,
+            0x1A => InputKey::Esc,
+            0x1B => InputKey::Gs,
+            0x1C => InputKey::Cr,
+            0x1E => InputKey::Soh,
+            0x1F => InputKey::Dc3,
+            0x20 => InputKey::Eot,
+            0x21 => InputKey::Ack,
+            0x22 => InputKey::Bel,
+            0x23 => InputKey::Bs,
+            0x24 => InputKey::Lf,
+            0x25 => InputKey::Vt,
+            0x26 => InputKey::Ff,
+            0x27 => InputKey::SemiColon,
+            0x28 => InputKey::SingleQuote,
+            0x29 => InputKey::Backtick,
+            0x2B => InputKey::Fs,
+            0x2C => InputKey::Sub,
+            0x2D => InputKey::Can,
+            0x2E => InputKey::Etx,
+            0x2F => InputKey::Syn,
+            0x30 => InputKey::Stx,
+            0x31 => InputKey::So,
+            0x32 => InputKey::Cr,
+            0x33 => InputKey::Comma,
+            0x34 => InputKey::Period,
+            0x35 => InputKey::Us,
+            _ => InputKey::Ign,
+        }
+    }
+}
+
+fn parse_inputkey() -> InputKey {
+    static CAPS_LOCK: AtomicBool = AtomicBool::new(false); // CapsLock key state
+    static SHIFT_KEY: AtomicBool = AtomicBool::new(false); // Shift key pressed
+    static CTRL_KEY: AtomicBool = AtomicBool::new(false); // Ctrl key pressed
+
+    let status = Status::read();
+    let code = ScanCode::read();
+
+    if status.has_error() || code.has_error() {
+        log::warn!(
+            "i8042 keyboard error detected, code:{:?} status:{:?}",
+            code,
+            status
+        );
+        return InputKey::Ign;
+    }
+
+    if !status.has_data_to_read() {
+        log::warn!("i8042 keyboard has no data to read");
+        return InputKey::Ign;
+    }
+
+    // TODO: handle the scancodes with extended byte (0xE0).
+    //
+    // This generates two different interrupts: the first containing 0xE0, the second containing the scancode.
+    if code.is_extension() {
+        return InputKey::Ign;
+    }
+
+    // Handle the Ctrl key, holds the state.
+    if code.is_ctrl() {
+        if code.is_pressed() {
+            CTRL_KEY.store(true, Ordering::Relaxed);
+        } else {
+            CTRL_KEY.store(false, Ordering::Relaxed);
+        }
+        return InputKey::Ign;
+    }
+
+    // Handle the Shift key, holds the state.
+    if code.is_shift() {
+        if code.is_pressed() {
+            SHIFT_KEY.store(true, Ordering::Relaxed);
+        } else {
+            SHIFT_KEY.store(false, Ordering::Relaxed);
+        }
+        return InputKey::Ign;
+    }
+
+    // Ignore other release events.
+    if code.is_released() {
+        return InputKey::Ign;
+    }
+
+    if code.is_caps_lock() {
+        CAPS_LOCK.fetch_xor(true, Ordering::Relaxed);
+        return InputKey::Ign;
+    }
+
+    let ctrl_key = CTRL_KEY.load(Ordering::Relaxed);
+    let shift_key = SHIFT_KEY.load(Ordering::Relaxed);
+    let caps_lock = CAPS_LOCK.load(Ordering::Relaxed);
+    if ctrl_key {
+        code.ctrl_map()
+    } else if shift_key || caps_lock {
+        code.shift_map()
+    } else {
+        code.plain_map()
+    }
+}
