+pub(super) static STATUS_OR_COMMAND_PORT: Once<IoPort<u8, ReadWriteAccess>> = Once::new();
+
+pub(super) fn init() -> Result<(), ComponentInitError> {
+    // TODO: Check the flags in the ACPI table to determine if the PS/2 controller exists. See:
+    // <https://uefi.org/specs/ACPI/6.5/05_ACPI_Software_Programming_Model.html#ia-pc-boot-architecture-flags>.
+
+    let data_port = IoPort::acquire(0x60).unwrap();
+    let status_or_command_port = IoPort::acquire(0x64).unwrap();
+
+    // Disable devices so that they won't send data at the wrong time and mess up initialisation.
+    status_or_command_port.write(0xAD);
+    status_or_command_port.write(0xA7);
+
+    // Flush the the output buffer by reading from port 0x60 and discarding the data.
+    let _ = data_port.read();
+
+    // Set the controller configuration byte.
+    status_or_command_port.write(0x20);
+    let mut config = Configuration::from_bits_truncate(data_port.read());
+    config.remove(
+        Configuration::FIRST_PORT_INTERRUPT_ENABLED
+            | Configuration::FIRST_PORT_TRANSLATION_ENABLED
+            | Configuration::SECOND_PORT_INTERRUPT_ENABLED,
+    );
+    status_or_command_port.write(0x60);
+    data_port.write(config.bits());
+
+    // Perform controller self-test.
+    // Any value other than 0x55 indicates a self-test fail. This can reset the PS/2 controller
+    // on some hardware (tested on a 2016 laptop). At the very least, the Controller Configuration
+    // Byte should be restored for compatibility with such hardware.
+    status_or_command_port.write(0xAA);
+    if data_port.read() != 0x55 {
+        return Err(ComponentInitError::UninitializedDependencies(
+            "I8042 controller self-test failed".to_string(),
+        ));
+    }
+
+    // Determine if there are 2 channels.
+    status_or_command_port.write(0xA8);
+    status_or_command_port.write(0x20);
+    let mut config = Configuration::from_bits_truncate(data_port.read());
+    if !config.contains(Configuration::SECOND_PORT_CLOCK_DISABLED) {
+        status_or_command_port.write(0xA7);
+        config.remove(
+            Configuration::SECOND_PORT_INTERRUPT_ENABLED
+                | Configuration::SECOND_PORT_CLOCK_DISABLED,
+        );
+        status_or_command_port.write(0x60);
+        data_port.write(config.bits());
+
+        // Perform interface tests to the second PS/2 port.
+        status_or_command_port.write(0xA9);
+        if data_port.read() != 0x00 {
+            return Err(ComponentInitError::UninitializedDependencies(
+                "I8042 interface tests failed (port 2)".to_string(),
+            ));
+        }
+        // Enable the second PS/2 port.
+        status_or_command_port.write(0xA8);
+        config.insert(Configuration::SECOND_PORT_INTERRUPT_ENABLED);
+    }
+
+    // Perform interface tests to the first PS/2 port.
+    status_or_command_port.write(0xAB);
+    if data_port.read() != 0x00 {
+        return Err(ComponentInitError::UninitializedDependencies(
+            "I8042 interface tests failed (port 1)".to_string(),
+        ));
+    }
+    // Enable the first PS/2 port.
+    status_or_command_port.write(0xAE);
+    config.remove(Configuration::FIRST_PORT_CLOCK_DISABLED);
+    config.insert(
+        Configuration::FIRST_PORT_INTERRUPT_ENABLED | Configuration::FIRST_PORT_TRANSLATION_ENABLED,
+    );
+    status_or_command_port.write(0x60);
+    data_port.write(config.bits());
+
+    // The controller initialisation is done, all PS/2 devices (if any) should be reset by the driver.
+
+    DATA_PORT.call_once(|| data_port);
+    STATUS_OR_COMMAND_PORT.call_once(|| status_or_command_port);
+    Ok(())
+}
+
+bitflags! {
+    /// The configuration of the PS/2 controller.
+    ///
+    /// Commands 0x20 and 0x60 let you read and write the PS/2 Controller Configuration.
+    pub(super) struct Configuration: u8 {
+        /// First PS/2 port interrupt (1 = enabled, 0 = disabled)
+        const FIRST_PORT_INTERRUPT_ENABLED = 1 << 0;
+        /// Second PS/2 port interrupt (1 = enabled, 0 = disabled, only if 2 PS/2 ports supported)
+        const SECOND_PORT_INTERRUPT_ENABLED = 1 << 1;
+        /// System Flag (1 = system passed POST, 0 = your OS shouldn't be running)
+        const SYSTEM_POST_PASSED = 1 << 2;
+        /// First PS/2 port clock (1 = disabled, 0 = enabled)
+        const FIRST_PORT_CLOCK_DISABLED = 1 << 4;
+        /// Second PS/2 port clock (1 = disabled, 0 = enabled, only if 2 PS/2 ports supported)
+        const SECOND_PORT_CLOCK_DISABLED = 1 << 5;
+        /// First PS/2 port translation (1 = enabled, 0 = disabled)
+        const FIRST_PORT_TRANSLATION_ENABLED = 1 << 6;
+    }
+}
+
+bitflags! {
+    /// The status of the i8042 PS/2 controller.
+    ///
+    /// Reference: <https://wiki.osdev.org/I8042_PS/2_Controller#Status_Register>.
+    pub(super) struct Status: u8 {
+        /// Output buffer status (0 = empty, 1 = full)
+        /// Must be set before attempting to read data from port 0x60.
+        const OUTPUT_BUFFER_IS_FULL = 1 << 0;
+        /// System Flag
+        /// Meant to be cleared on reset and set by firmware (via. PS/2 Controller Configuration Byte)
+        /// if the system passes self tests (POST).
+        const SYSTEM_FLAG = 1 << 2;
+        /// Time-out error (0 = no error, 1 = time-out error)
+        const TIME_OUT_ERROR = 1 << 6;
+        /// Parity error (0 = no error, 1 = parity error)
+        const PARITY_ERROR = 1 << 7;
+    }
+}
+
+impl Status {
+    pub(super) fn read() -> Self {
+        Self::from_bits_truncate(STATUS_OR_COMMAND_PORT.get().unwrap().read())
+    }
+
+    pub(super) fn has_data_to_read(&self) -> bool {
+        self.contains(Status::OUTPUT_BUFFER_IS_FULL)
+    }
+
+    pub(super) fn has_error(&self) -> bool {
+        self.contains(Self::SYSTEM_FLAG | Self::TIME_OUT_ERROR | Self::PARITY_ERROR)
+    }
+}
diff --git a/kernel/comps/keyboard/src/i8042_chip/keyboard.rs b/kernel/comps/keyboard/src/i8042_chip/keyboard.rs
new file mode 100644
index 000000000..cd7d7c897
--- /dev/null
+++ b/kernel/comps/keyboard/src/i8042_chip/keyboard.rs
@@ -0,0 +1,373 @@
+// SPDX-License-Identifier: MPL-2.0
+
+//! The i8042 keyboard driver.
+
+use alloc::string::ToString;
+use core::sync::atomic::{AtomicBool, Ordering};
+
+use component::ComponentInitError;
+use ostd::{
+    arch::kernel::{MappedIrqLine, IRQ_CHIP},
+    trap::{IrqLine, TrapFrame},
+};
+use spin::Once;
+
+use super::controller::{Status, DATA_PORT, STATUS_OR_COMMAND_PORT};
+use crate::{InputKey, KEYBOARD_CALLBACKS};
+
+/// IRQ line for i8042 keyboard.
+static IRQ_LINE: Once<MappedIrqLine> = Once::new();
+
+pub(super) fn init() -> Result<(), ComponentInitError> {
+    // TODO: maybe we should reset the keyboard device here?
+    //
+    // This can be done by sending 0xFF (reset command, supported by all PS/2 devices) to port 1
+    // and waiting for a response. If the response is 0xFA, 0xAA (Note: the order in which devices
+    // send these two seems to be ambiguous) followed by the device PS/2 ID, then the device reset
+    // was successful. If the response is 0xFC then the self test failed and the device should be
+    // ignored. If theres no response at all then the port is not populated.
+    //
+    // See <https://wiki.osdev.org/I8042_PS/2_Controller#Detecting_PS/2_Device_Types> for a list
+    // of the device PS/2 IDs.
+
+    let mut irq_line = IrqLine::alloc().unwrap();
+    irq_line.on_active(handle_keyboard_input);
+    let Ok(mappped_irq_line) = IRQ_CHIP.get().unwrap().map_isa_pin_to(irq_line, 1) else {
+        return Err(ComponentInitError::UninitializedDependencies(
+            "Map IRQ for i8042 kerboard failed".to_string(),
+        ));
+    };
+    IRQ_LINE.call_once(|| mappped_irq_line);
+    Ok(())
+}
+
+fn handle_keyboard_input(_trap_frame: &TrapFrame) {
+    if !DATA_PORT.is_completed() || !STATUS_OR_COMMAND_PORT.is_completed() {
+        return;
+    }
+
+    let key = parse_inputkey();
+    for callback in KEYBOARD_CALLBACKS.lock().iter() {
+        callback(key);
+    }
+}
+
+/// A scan code in the Scan Code Set 1.
+///
+/// Reference: <https://wiki.osdev.org/PS/2_Keyboard#Scan_Code_Set_1>.
+#[derive(Debug, Clone, Copy)]
+struct ScanCode(u8);
+
+impl ScanCode {
+    fn read() -> Self {
+        Self(DATA_PORT.get().unwrap().read())
+    }
+
+    fn has_error(&self) -> bool {
+        // Key detection error or internal buffer overrun.
+        self.0 == 0xFF
+    }
+
+    fn is_pressed(&self) -> bool {
+        self.0 & 0x80 == 0
+    }
+
+    fn is_released(&self) -> bool {
+        self.0 & 0x80 != 0
+    }
+
+    fn is_shift(&self) -> bool {
+        let code = self.0 & 0x7F;
+        // Left/right shift codes
+        code == 0x2A || code == 0x36
+    }
+
+    fn is_ctrl(&self) -> bool {
+        let code = self.0 & 0x7F;
+        // Left/right ctrl codes
+        code == 0x1D
+    }
+
+    fn is_caps_lock(&self) -> bool {
+        self.0 == 0x3A
+    }
+
+    fn is_extension(&self) -> bool {
+        self.0 == 0xE0
+    }
+
+    fn plain_map(&self) -> InputKey {
+        match self.0 & 0x7F {
+            0x01 => InputKey::Esc,
+            0x02 => InputKey::One,
+            0x03 => InputKey::Two,
+            0x04 => InputKey::Three,
+            0x05 => InputKey::Four,
+            0x06 => InputKey::Five,
+            0x07 => InputKey::Six,
+            0x08 => InputKey::Seven,
+            0x09 => InputKey::Eight,
+            0x0A => InputKey::Nine,
+            0x0B => InputKey::Zero,
+            0x0C => InputKey::Minus,
+            0x0D => InputKey::Equal,
+            0x0E => InputKey::Del,
+            0x0F => InputKey::Tab,
+            0x10 => InputKey::LowercaseQ,
+            0x11 => InputKey::LowercaseW,
+            0x12 => InputKey::LowercaseE,
+            0x13 => InputKey::LowercaseR,
+            0x14 => InputKey::LowercaseT,
+            0x15 => InputKey::LowercaseY,
+            0x16 => InputKey::LowercaseU,
+            0x17 => InputKey::LowercaseI,
+            0x18 => InputKey::LowercaseO,
+            0x19 => InputKey::LowercaseP,
+            0x1A => InputKey::LeftBracket,
+            0x1B => InputKey::RightBracket,
+            0x1C => InputKey::Cr,  // Enter
+            0x1D => InputKey::Ign, // Left Ctrl
+            0x1E => InputKey::LowercaseA,
+            0x1F => InputKey::LowercaseS,
+            0x20 => InputKey::LowercaseD,
+            0x21 => InputKey::LowercaseF,
+            0x22 => InputKey::LowercaseG,
+            0x23 => InputKey::LowercaseH,
+            0x24 => InputKey::LowercaseJ,
+            0x25 => InputKey::LowercaseK,
+            0x26 => InputKey::LowercaseL,
+            0x27 => InputKey::SemiColon,
+            0x28 => InputKey::SingleQuote,
+            0x29 => InputKey::Backtick,
+            0x2A => InputKey::Ign, // Left Shift
+            0x2B => InputKey::BackSlash,
+            0x2C => InputKey::LowercaseZ,
+            0x2D => InputKey::LowercaseX,
+            0x2E => InputKey::LowercaseC,
+            0x2F => InputKey::LowercaseV,
+            0x30 => InputKey::LowercaseB,
+            0x31 => InputKey::LowercaseN,
+            0x32 => InputKey::LowercaseM,
+            0x33 => InputKey::Comma,
+            0x34 => InputKey::Period,
+            0x35 => InputKey::ForwardSlash,
+            0x36 => InputKey::Ign,      // Right Shift
+            0x37 => InputKey::Asterisk, // Keypad-* or (*/PrtScn) on a 83/84-key keyboard
+            0x38 => InputKey::Ign,      // Left Alt
+            0x39 => InputKey::Space,
+            0x3A => InputKey::Ign, // CapsLock
+            0x3B => InputKey::F1,
+            0x3C => InputKey::F2,
+            0x3D => InputKey::F3,
+            0x3E => InputKey::F4,
+            0x3F => InputKey::F5,
+            0x40 => InputKey::F6,
+            0x41 => InputKey::F7,
+            0x42 => InputKey::F8,
+            0x43 => InputKey::F9,
+            0x44 => InputKey::F10,
+            0x45 => InputKey::Ign,        // NumLock
+            0x46 => InputKey::Ign,        // ScrollLock
+            0x47 => InputKey::Home,       // Keypad-7 or Home
+            0x48 => InputKey::UpArrow,    // Keypad-8 or Up
+            0x49 => InputKey::PageUp,     // Keypad-9 or PageUp
+            0x4A => InputKey::Minus,      // Keypad--
+            0x4B => InputKey::LeftArrow,  // Keypad-4 or Left
+            0x4C => InputKey::Five,       // Keypad-5
+            0x4D => InputKey::RightArrow, // Keypad-6 or Right
+            0x4E => InputKey::Plus,       // Keypad-+
+            0x4F => InputKey::End,        // Keypad-1 or End
+            0x50 => InputKey::DownArrow,  // Keypad-2 or Down
+            0x51 => InputKey::PageDown,   // Keypad-3 or PageDown
+            0x52 => InputKey::Insert,     // Keypad-0 or Insert
+            0x53 => InputKey::Delete,     // Keypad-. or Del
+            0x57 => InputKey::F11,
+            0x58 => InputKey::F12,
+            _ => InputKey::Ign,
+        }
+    }
+
+    fn shift_map(&self) -> InputKey {
+        match self.0 & 0x7F {
+            0x01 => InputKey::Esc,
+            0x02 => InputKey::Exclamation,
+            0x03 => InputKey::At,
+            0x04 => InputKey::Hash,
+            0x05 => InputKey::Dollar,
+            0x06 => InputKey::Percent,
+            0x07 => InputKey::Caret,
+            0x08 => InputKey::Ampersand,
+            0x09 => InputKey::Asterisk,
+            0x0A => InputKey::LeftParen,
+            0x0B => InputKey::RightParen,
+            0x0C => InputKey::Underscore,
+            0x0D => InputKey::Plus,
+            0x0E => InputKey::Del,
+            0x0F => InputKey::Tab,
+            0x10 => InputKey::UppercaseQ,
+            0x11 => InputKey::UppercaseW,
+            0x12 => InputKey::UppercaseE,
+            0x13 => InputKey::UppercaseR,
+            0x14 => InputKey::UppercaseT,
+            0x15 => InputKey::UppercaseY,
+            0x16 => InputKey::UppercaseU,
+            0x17 => InputKey::UppercaseI,
+            0x18 => InputKey::UppercaseO,
+            0x19 => InputKey::UppercaseP,
+            0x1A => InputKey::LeftBrace,
+            0x1B => InputKey::RightBrace,
+            0x1C => InputKey::Cr,
+            0x1E => InputKey::UppercaseA,
+            0x1F => InputKey::UppercaseS,
+            0x20 => InputKey::UppercaseD,
+            0x21 => InputKey::UppercaseF,
+            0x22 => InputKey::UppercaseG,
+            0x23 => InputKey::UppercaseH,
+            0x24 => InputKey::UppercaseJ,
+            0x25 => InputKey::UppercaseK,
+            0x26 => InputKey::UppercaseL,
+            0x27 => InputKey::Colon,
+            0x28 => InputKey::DoubleQuote,
+            0x29 => InputKey::Tilde,
+            0x2B => InputKey::Pipe,
+            0x2C => InputKey::UppercaseZ,
+            0x2D => InputKey::UppercaseX,
+            0x2E => InputKey::UppercaseC,
+            0x2F => InputKey::UppercaseV,
+            0x30 => InputKey::UppercaseB,
+            0x31 => InputKey::UppercaseN,
+            0x32 => InputKey::UppercaseM,
+            0x33 => InputKey::LessThan,
+            0x34 => InputKey::GreaterThan,
+            0x35 => InputKey::Question,
+            0x39 => InputKey::Space,
+            _ => InputKey::Ign,
+        }
+    }
+
+    fn ctrl_map(&self) -> InputKey {
+        match self.0 & 0x7F {
+            0x02 => InputKey::One,
+            0x03 => InputKey::Nul,
+            0x04 => InputKey::Esc,
+            0x05 => InputKey::Fs,
+            0x06 => InputKey::Gs,
+            0x07 => InputKey::Rs,
+            0x08 => InputKey::Us,
+            0x09 => InputKey::Del,
+            0x0A => InputKey::Nine,
+            0x0B => InputKey::Zero,
+            0x0C => InputKey::Us,
+            0x0D => InputKey::Equal,
+            0x0E => InputKey::Bs,
+            0x10 => InputKey::Dc1,
+            0x11 => InputKey::Etb,
+            0x12 => InputKey::Enq,
+            0x13 => InputKey::Dc2,
+            0x14 => InputKey::Dc4,
+            0x15 => InputKey::Em,
+            0x16 => InputKey::Nak,
+            0x17 => InputKey::Tab,
+            0x18 => InputKey::Si,
+            0x19 => InputKey::Dle,
+            0x1A => InputKey::Esc,
+            0x1B => InputKey::Gs,
+            0x1C => InputKey::Cr,
+            0x1E => InputKey::Soh,
+            0x1F => InputKey::Dc3,
+            0x20 => InputKey::Eot,
+            0x21 => InputKey::Ack,
+            0x22 => InputKey::Bel,
+            0x23 => InputKey::Bs,
+            0x24 => InputKey::Lf,
+            0x25 => InputKey::Vt,
+            0x26 => InputKey::Ff,
+            0x27 => InputKey::SemiColon,
+            0x28 => InputKey::SingleQuote,
+            0x29 => InputKey::Backtick,
+            0x2B => InputKey::Fs,
+            0x2C => InputKey::Sub,
+            0x2D => InputKey::Can,
+            0x2E => InputKey::Etx,
+            0x2F => InputKey::Syn,
+            0x30 => InputKey::Stx,
+            0x31 => InputKey::So,
+            0x32 => InputKey::Cr,
+            0x33 => InputKey::Comma,
+            0x34 => InputKey::Period,
+            0x35 => InputKey::Us,
+            _ => InputKey::Ign,
+        }
+    }
+}
+
+fn parse_inputkey() -> InputKey {
+    static CAPS_LOCK: AtomicBool = AtomicBool::new(false); // CapsLock key state
+    static SHIFT_KEY: AtomicBool = AtomicBool::new(false); // Shift key pressed
+    static CTRL_KEY: AtomicBool = AtomicBool::new(false); // Ctrl key pressed
+
+    let status = Status::read();
+    let code = ScanCode::read();
+
+    if status.has_error() || code.has_error() {
+        log::warn!(
+            "i8042 keyboard error detected, code:{:?} status:{:?}",
+            code,
+            status
+        );
+        return InputKey::Ign;
+    }
+
+    if !status.has_data_to_read() {
+        log::warn!("i8042 keyboard has no data to read");
+        return InputKey::Ign;
+    }
+
+    // TODO: handle the scancodes with extended byte (0xE0).
+    //
+    // This generates two different interrupts: the first containing 0xE0, the second containing the scancode.
+    if code.is_extension() {
+        return InputKey::Ign;
+    }
+
+    // Handle the Ctrl key, holds the state.
+    if code.is_ctrl() {
+        if code.is_pressed() {
+            CTRL_KEY.store(true, Ordering::Relaxed);
+        } else {
+            CTRL_KEY.store(false, Ordering::Relaxed);
+        }
+        return InputKey::Ign;
+    }
+
+    // Handle the Shift key, holds the state.
+    if code.is_shift() {
+        if code.is_pressed() {
+            SHIFT_KEY.store(true, Ordering::Relaxed);
+        } else {
+            SHIFT_KEY.store(false, Ordering::Relaxed);
+        }
+        return InputKey::Ign;
+    }
+
+    // Ignore other release events.
+    if code.is_released() {
+        return InputKey::Ign;
+    }
+
+    if code.is_caps_lock() {
+        CAPS_LOCK.fetch_xor(true, Ordering::Relaxed);
+        return InputKey::Ign;
+    }
+
+    let ctrl_key = CTRL_KEY.load(Ordering::Relaxed);
+    let shift_key = SHIFT_KEY.load(Ordering::Relaxed);
+    let caps_lock = CAPS_LOCK.load(Ordering::Relaxed);
+    if ctrl_key {
+        code.ctrl_map()
+    } else if shift_key || caps_lock {
+        code.shift_map()
+    } else {
+        code.plain_map()
+    }
+}
